public class Foo {
    void m(Runnable r) {
        try {
            r.run();
        } catch (Error e) {
            System.out.println("error");
        } catch (Throwable t) {
            System.out.println("throwable");
        }
    }
}

public class Foo {
    void m(java.util.concurrent.Callable<String> c) {
        try {
            c.call();
        } catch (RuntimeException e) {
            System.out.println("runtime");
        } catch (Exception e) {
            System.out.println("exception");
        }
    }
}
